65:#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
66:pub(crate) struct CoordinatorHandoff {
67:    pub(crate) body: String,
68:    /// Unix epoch seconds.
69:    pub(crate) written_at: i64,
70:    /// Spawn token of the coordinator record that was live at write time.
71:    /// Empty when no coordinator record existed (a handoff written from a
72:    /// plain terminal before any coordinator ever ran).
