245:/// Everything [`compose_start_brief`] needs; kept as a struct so the
246:/// composer stays pure and directly testable.
247:pub(crate) struct StartBriefInputs<'a> {
248:    pub(crate) state: &'a HandoffState,
249:    pub(crate) previous: Option<&'a PreviousSession>,
250:    pub(crate) reason: CoordinatorStartReason,
251:    pub(crate) now_epoch_secs: i64,
252:    /// Directory holding prior sessions' Claude Code transcripts, when the
253:    /// caller verified it exists. Mentioned as a slow last resort only.
254:    pub(crate) transcript_dir: Option<&'a Path>,
255:}
256:
257:fn when(epoch: i64, now: i64) -> String {
258:    match format_elapsed_ago(epoch, now) {
259:        Some(ago) => format!("{ago} ({})", format_epoch_iso8601(epoch)),
260:        None => format_epoch_iso8601(epoch),
261:    }
262:}
263:
264:/// Render the session-start brief handed to a fresh coordinator session
265:/// as its initial prompt. Pure over its inputs.
266:pub(crate) fn compose_start_brief(inputs: StartBriefInputs<'_>) -> String {
267:    let StartBriefInputs {
268:        state,
269:        previous,
270:        reason,
271:        now_epoch_secs: now,
272:        transcript_dir,
273:    } = inputs;
274:    let mut out = String::new();
275:    out.push_str("[Boss coordinator session start: automatic handoff brief from the engine]\n\n");
276:    out.push_str(&format!(
277:        "You are a fresh coordinator session; {}. Everything the operator told the previous session is gone from \
278:         your context. What follows is the engine's report on the session handoff.\n\n",
279:        reason.describe()
280:    ));
281:
282:    let previous_started = previous.and_then(|p| p.spawned_at).map(|at| when(at, now));
283:    let previous_phrase = match (&previous_started, previous) {
284:        (Some(started), _) => format!("the session that just ended (started {started})"),
285:        (None, Some(_)) => "the session that just ended".to_owned(),
286:        (None, None) => "the previous session".to_owned(),
287:    };
288:
289:    match state {
290:        HandoffState::Present(handoff) => {
291:            let written = when(handoff.written_at, now);
292:            let by_previous =
293:                previous.is_some_and(|p| !p.spawn_token.is_empty() && p.spawn_token == handoff.writer_spawn_token);
294:            if by_previous {
295:                out.push_str(&format!(
296:                    "HANDOFF PRESENT: written by {previous_phrase}, {written}. Facts in it are current as of that \
297:                     time, not now.\n"
298:                ));
299:            } else if handoff.writer_spawn_token.is_empty() {
300:                out.push_str(&format!(
301:                    "HANDOFF PRESENT (writer unknown): a handoff was written {written}, but the engine has no record \
302:                     of the session that wrote it. Treat it as possibly stale and confirm its facts with the \
303:                     operator.\n"
304:                ));
305:            } else if previous.is_some() {
306:                out.push_str(&format!(
307:                    "HANDOFF STALE: {previous_phrase} never wrote a handoff. The newest handoff, below, was written \
308:                     by an EARLIER session, {written}. Everything the operator told the session that just ended is \
309:                     NOT in it. Say so in your first reply and ask the operator what changed since then before \
310:                     relying on any of it.\n"
311:                ));
312:            } else {
313:                out.push_str(&format!(
314:                    "HANDOFF PRESENT (writer unknown): a handoff was written {written}, but the engine has no record \
315:                     of the session that wrote it. Treat it as possibly stale and confirm its facts with the \
316:                     operator.\n"
317:                ));
318:            }
319:            out.push_str("--- handoff begins ---\n");
320:            out.push_str(handoff.body.trim_end());
321:            out.push_str("\n--- handoff ends ---\n");
322:        }
323:        HandoffState::Missing => {
324:            if reason == CoordinatorStartReason::FirstCreation && previous.is_none() {
325:                out.push_str(
326:                    "NO HANDOFF: none is expected. This is the first coordinator session on this engine, so there \
327:                     is no previous session to hand anything off.\n",
328:                );
329:            } else {
330:                out.push_str(&format!(
331:                    "NO HANDOFF AVAILABLE: no coordinator session has ever written one, so {previous_phrase} left \
332:                     nothing behind. This is NOT the same as \"nothing to hand off\": anything the operator said \
333:                     in that session (infrastructure taken down or brought back, flags flipped, decisions, things \
334:                     not to do) is lost unless they repeat it. Say so in your first reply and ask the operator \
335:                     what you should know before you act on anything.\n"
336:                ));
337:            }
338:        }
339:        HandoffState::Unreadable(error) => {
340:            out.push_str(&format!(
341:                "HANDOFF UNREADABLE: a handoff is stored but the engine could not read it: {error}. Treat this \
342:                 exactly like a missing handoff ({previous_phrase} may have written facts you cannot see), tell \
343:                 the operator the stored handoff is unreadable so it can be investigated, and ask them what you \
344:                 should know before you act on anything.\n"
345:            ));
346:        }
347:    }
348:
349:    if let Some(dir) = transcript_dir {
350:        out.push_str(&format!(
351:            "\nLast resort only: prior sessions' Claude Code transcripts are under {} (newest *.jsonl by mtime). \
352:             Grepping them is slow and unreliable; use it only when the handoff is missing or stale and the \
353:             operator is unavailable, never as a substitute for asking.\n",
354:            dir.display()
355:        ));
356:    }
357:
358:    out.push_str(
359:        "\nDo this now, before anything else:\n\
360:         1. Your first reply states which handoff state applies (present / stale / missing / unreadable) in one \
361:         line, then summarizes the handoff in a few lines if there is one.\n\
362:         2. Treat every infrastructure, host, flag, tmux, or pause fact from the handoff as \"as of the time it was \
363:         written\". Before filing work, briefing an agent, or raising an alarm that depends on such a fact, \
364:         confirm it is still true (a fresh read, or ask the operator).\n\
365:         3. Once absorbed, write a fresh handoff via `boss handoff write` carrying forward what is still true, so \
366:         the next restart is handed THIS session's knowledge. Then keep it current: refresh it whenever the \
367:         operator states a fact that changed the world, makes a decision, or says not to do something. The \
368:         \"Session handoff\" section of your instructions has the format.\n",
369:    );
370:    out
371:}
372:
373:/// Claude Code stores a project's transcripts under
374:/// `~/.claude/projects/<encoded cwd>/`, where the encoding replaces every
375:/// character outside `[A-Za-z0-9]` with `-`. Pure; the caller decides
376:/// whether the directory actually exists.
377:pub(crate) fn transcript_projects_dir(home: &Path, working_directory: &Path) -> PathBuf {
378:    let encoded: String = working_directory
379:        .to_string_lossy()
380:        .chars()
381:        .map(|c| if c.is_ascii_alphanumeric() { c } else { '-' })
382:        .collect();
383:    home.join(".claude").join("projects").join(encoded)
384:}
385:
386:/// [`transcript_projects_dir`] for the real `$HOME`, only when it exists.
387:pub(crate) fn existing_transcript_dir(working_directory: &Path) -> Option<PathBuf> {
388:    let home = std::env::var_os("HOME")?;
389:    let dir = transcript_projects_dir(Path::new(&home), working_directory);
390:    dir.is_dir().then_some(dir)
391:}
392:
393:/// Write the brief where the coordinator's launch command reads it from.
394:/// Returns the absolute path written.
395:pub(crate) fn write_start_brief(working_directory: &Path, brief: &str) -> Result<PathBuf> {
396:    let dir = working_directory.join(".claude");
397:    std::fs::create_dir_all(&dir).with_context(|| format!("creating {}", dir.display()))?;
398:    let path = dir.join(START_BRIEF_FILENAME);
399:    std::fs::write(&path, brief).with_context(|| format!("writing session-start brief to {}", path.display()))?;
400:    Ok(path)
401:}
