404:mod tests {
405:    use super::*;
406:
407:    const NOW: i64 = 1_756_800_000;
408:
409:    fn present(written_at: i64, writer: &str) -> HandoffState {
410:        HandoffState::Present(CoordinatorHandoff {
411:            body: "- greyarea is shut down (operator, 19:22 PDT)\n- tmux hosting re-enabled\n".to_owned(),
412:            written_at,
413:            writer_spawn_token: writer.to_owned(),
414:        })
415:    }
416:
417:    fn previous(token: &str, spawned_at: Option<i64>) -> PreviousSession {
418:        PreviousSession {
419:            spawn_token: token.to_owned(),
420:            spawned_at,
421:        }
422:    }
423:
424:    fn brief(state: &HandoffState, previous: Option<&PreviousSession>, reason: CoordinatorStartReason) -> String {
425:        compose_start_brief(StartBriefInputs {
426:            state,
427:            previous,
428:            reason,
429:            now_epoch_secs: NOW,
430:            transcript_dir: None,
431:        })
432:    }
433:
434:    #[test]
435:    fn validate_trims_and_rejects_blank_bodies() {
436:        assert_eq!(validate_handoff_body("  - fact \n\n").unwrap(), "- fact");
437:        let err = validate_handoff_body(" \n\t").unwrap_err();
438:        assert!(err.contains("empty"), "got: {err}");
439:    }
440:
441:    #[test]
442:    fn validate_rejects_oversize_bodies_with_the_cap_named() {
443:        let big = "x".repeat(MAX_HANDOFF_BYTES + 1);
444:        let err = validate_handoff_body(&big).unwrap_err();
445:        assert!(err.contains(&MAX_HANDOFF_BYTES.to_string()), "got: {err}");
446:        assert!(validate_handoff_body(&"x".repeat(MAX_HANDOFF_BYTES)).is_ok());
447:    }
448:
449:    #[test]
450:    fn state_distinguishes_missing_present_and_unreadable() {
451:        let db = WorkDb::open(PathBuf::from(":memory:")).unwrap();
452:        assert_eq!(db.coordinator_handoff_state(), HandoffState::Missing);
453:
454:        let written = db.set_coordinator_handoff("- fact", "token-a", NOW).unwrap();
455:        assert_eq!(db.coordinator_handoff_state(), HandoffState::Present(written));
456:
457:        db.set_metadata(HANDOFF_METADATA_KEY, "{not json").unwrap();
458:        match db.coordinator_handoff_state() {
459:            HandoffState::Unreadable(reason) => assert!(reason.contains("not valid JSON"), "got: {reason}"),
460:            other => panic!("corrupt value must read as Unreadable, got {other:?}"),
461:        }
462:    }
463:
464:    #[test]
465:    fn view_marks_current_session_only_on_exact_token_match() {
466:        let handoff = CoordinatorHandoff {
467:            body: "- fact".to_owned(),
468:            written_at: NOW - 240,
469:            writer_spawn_token: "token-a".to_owned(),
470:        };
471:        let view = handoff_view(&handoff, Some("token-a"), NOW);
472:        assert!(view.written_by_current_session);
473:        assert_eq!(view.age_secs, 240);
474:        assert_eq!(view.written_at_iso8601, format_epoch_iso8601(NOW - 240));
475:        assert!(!handoff_view(&handoff, Some("token-b"), NOW).written_by_current_session);
476:        assert!(!handoff_view(&handoff, None, NOW).written_by_current_session);
477:
478:        let anonymous = CoordinatorHandoff {
479:            writer_spawn_token: String::new(),
480:            ..handoff
481:        };
482:        assert!(
483:            !handoff_view(&anonymous, Some(""), NOW).written_by_current_session,
484:            "an empty writer token must never match, even against an empty current token"
485:        );
486:    }
487:
488:    #[test]
489:    fn brief_reports_a_handoff_written_by_the_session_that_just_ended() {
490:        let state = present(NOW - 240, "token-a");
491:        let prev = previous("token-a", Some(NOW - 3600));
492:        let text = brief(&state, Some(&prev), CoordinatorStartReason::PaneDead);
493:        assert!(
494:            text.contains("HANDOFF PRESENT: written by the session that just ended"),
495:            "{text}"
496:        );
497:        assert!(text.contains("4 minutes ago"), "{text}");
498:        assert!(
499:            text.contains("--- handoff begins ---\n- greyarea is shut down"),
500:            "{text}"
501:        );
502:        assert!(text.contains("claude process exited"), "{text}");
503:        assert!(!text.contains("STALE"), "{text}");
504:    }
505:
506:    #[test]
507:    fn brief_flags_a_handoff_left_by_an_earlier_session_as_stale() {
508:        // The ended session (token-b) never refreshed the handoff token-a
509:        // wrote: an abrupt kill must read as a gap, not as a handoff.
510:        let state = present(NOW - 3 * 86_400, "token-a");
511:        let prev = previous("token-b", Some(NOW - 7200));
512:        let text = brief(&state, Some(&prev), CoordinatorStartReason::SessionMissing);
513:        assert!(text.contains("HANDOFF STALE"), "{text}");
514:        assert!(text.contains("never wrote a handoff"), "{text}");
515:        assert!(text.contains("3 days ago"), "{text}");
516:        assert!(text.contains("started 2 hours ago"), "{text}");
517:        assert!(text.contains("--- handoff begins ---"), "{text}");
518:    }
