        );
    }

    #[test]
    fn rejects_unparseable_version_output() {
        assert_eq!(parse_claude_version(""), None);
        assert_eq!(parse_claude_version("\n"), None);
        assert_eq!(parse_claude_version("command not found\n"), None);
        assert_eq!(
            parse_claude_version("v2.1.237\n"),
