    let elapsed = now_secs.checked_sub(epoch_secs)?;
    if elapsed < 0 {
        return None;
    }
    let phrase = if elapsed < 60 {
        "just now".to_owned()
    } else if elapsed < 3600 {
        let n = elapsed / 60;
        if n == 1 {
            "1 minute ago".to_owned()
        } else {
            format!("{n} minutes ago")
        }
    } else if elapsed < 86_400 {
        let n = elapsed / 3600;
        if n == 1 {
            "1 hour ago".to_owned()
        } else {
            format!("{n} hours ago")
        }
    } else if elapsed < 86_400 * 30 {
        let n = elapsed / 86_400;
        if n == 1 {
