102:/// Restart a previously-created coordinator whose tmux session or child has
103:/// disappeared. This never creates the singleton from scratch: first
104:/// creation remains tied to app registration, after the app has prepared the
105:/// coordinator's isolated session directory.
106:///
107:/// Returns the replacement record only when the viewer must reattach. A
108:/// healthy session and a live model mismatch are deliberately left alone.
109:pub(crate) async fn restart_if_dead(spawn: &CoordinatorSpawn<'_>) -> Result<Option<CoordinatorTmuxRecord>> {
110:    let Some(record) = spawn.work_db.coordinator_tmux_record()? else {
111:        return Ok(None);
112:    };
113:    if !session_exists(spawn.tmux, &record.session_name).await? {
114:        return start_new(spawn, CoordinatorStartReason::SessionMissing).await.map(Some);
115:    }
116:    let live_token = spawn
117:        .tmux
118:        .show_environment(&record.session_name, SPAWN_TOKEN_ENV)
119:        .await?;
120:    match live_token {
121:        Some(token) if token == record.spawn_token => {
122:            crate::tmux_session_options::apply(spawn.tmux, &record.session_name)
123:                .await
124:                .context("applying Boss coordinator tmux session options")?;
125:        }
126:        Some(_) => bail!("coordinator tmux token does not match the metadata singleton"),
127:        None => bail!("coordinator tmux session exists without the metadata singleton token"),
128:    }
129:    if spawn
130:        .tmux
131:        .display_message(&record.session_name, DisplayField::PaneDead)
132:        .await?
133:        .trim()
134:        != "1"
135:    {
136:        if record.spawn_state == "intended" {
137:            confirm_existing_intent(spawn.work_db, spawn.tmux, &record).await?;
138:        }
139:        return Ok(None);
140:    }
141:    spawn
142:        .tmux
143:        .kill_session_verified(&record.session_name, &record.spawn_token)
144:        .await
145:        .context("removing dead coordinator tmux session before restart")?;
146:    start_new(spawn, CoordinatorStartReason::PaneDead).await.map(Some)
147:}
