149:/// Consecutive-failure tracker for the coordinator tmux supervisor.
150:///
151:/// Counts consecutive failed supervisor passes. A failed pass
152:/// (`restart_if_dead` returning `Err`, or a session directory that cannot
153:/// be resolved) increments; a healthy or recovered pass resets the count.
154:/// Reaching `LIMIT` raises the operator-facing restart-failure ceiling
155:/// attention once per streak.
156:///
157:/// The count is consecutive, not windowed: the supervisor already backs off
158:/// a full minute between hard failures, so a wall-clock window of that same
159:/// minute would reset the counter on every retry and the ceiling would still
160:/// never fire.
161:///
162:/// Separately tracks consecutive *successful* restarts (`Ok(Some(record))`
163:/// from `restart_if_dead`): a coordinator whose `claude` child exits
164:/// immediately (bad model, expired auth, `claude` missing from `PATH`) kills
165:/// and recreates the tmux session on every pass, which is a technically
166:/// successful restart and never touches the failure counter above. Left
167:/// unchecked that churns forever with no backoff and no operator signal, so
168:/// `record_restart` gives that path its own escalating backoff and its own
169:/// ceiling attention, reset only by a genuinely idle pass (`Ok(None)`).
170:pub(crate) struct CoordinatorRestartFailures {
171:    consecutive_failures: u32,
172:    ceiling_notified: bool,
173:    restart_churn: u32,
174:    restart_churn_notified: bool,
175:}
176:
177:/// What the supervisor should do after recording a failed pass.
178:pub(crate) struct RestartFailureDecision {
179:    pub delay: Duration,
180:    /// Raise the operator attention; true only the first time we reach the ceiling.
181:    pub notify: bool,
182:}
183:
184:/// What the supervisor should do after recording a successful restart.
185:pub(crate) struct RestartChurnDecision {
186:    pub delay: Duration,
187:    /// Raise the operator attention; true only the first time we reach the ceiling.
188:    pub notify: bool,
189:}
190:
191:impl CoordinatorRestartFailures {
192:    pub(crate) const LIMIT: u32 = 5;
193:    pub(crate) const BACKOFF_CAP: Duration = Duration::from_secs(60);
194:
195:    pub(crate) fn new() -> Self {
196:        Self {
197:            consecutive_failures: 0,
198:            ceiling_notified: false,
199:            restart_churn: 0,
200:            restart_churn_notified: false,
201:        }
202:    }
203:
204:    pub(crate) fn consecutive_failures(&self) -> u32 {
205:        self.consecutive_failures
206:    }
207:
208:    pub(crate) fn restart_churn(&self) -> u32 {
209:        self.restart_churn
210:    }
211:
212:    /// Record a genuinely healthy pass: no restart was needed. Resets both
213:    /// the failure counter and the restart-churn counter.
214:    pub(crate) fn record_success(&mut self) {
215:        self.consecutive_failures = 0;
216:        self.ceiling_notified = false;
217:        self.restart_churn = 0;
218:        self.restart_churn_notified = false;
219:    }
220:
221:    /// Record a failed pass (`Err`, or session directory not ready). The
222:    /// retry cadence stays flat at `BACKOFF_CAP` once the ceiling is
223:    /// reached — the supervisor keeps retrying, it does not pause.
224:    pub(crate) fn record_failure(&mut self) -> RestartFailureDecision {
225:        self.consecutive_failures = self.consecutive_failures.saturating_add(1);
226:        if self.consecutive_failures < Self::LIMIT {
227:            return RestartFailureDecision {
228:                delay: Self::BACKOFF_CAP,
229:                notify: false,
230:            };
231:        }
232:        let notify = !self.ceiling_notified;
233:        self.ceiling_notified = true;
234:        RestartFailureDecision {
235:            delay: Self::BACKOFF_CAP,
236:            notify,
237:        }
238:    }
239:
240:    /// Record a successful kill-and-recreate (`Ok(Some(record))`). This is
241:    /// not an `Err`, so it resets the hard-failure counter, but it escalates
242:    /// its own backoff (2s, 4s, 8s, 16s, 32s, capped at `BACKOFF_CAP`) so a
243:    /// crash-looping `claude` child cannot respawn every 2s forever, and
244:    /// raises its own ceiling attention once per streak.
245:    pub(crate) fn record_restart(&mut self) -> RestartChurnDecision {
246:        self.consecutive_failures = 0;
247:        self.ceiling_notified = false;
248:        self.restart_churn = self.restart_churn.saturating_add(1);
249:        let delay = Self::churn_backoff(self.restart_churn);
250:        if self.restart_churn < Self::LIMIT {
251:            return RestartChurnDecision { delay, notify: false };
252:        }
253:        let notify = !self.restart_churn_notified;
254:        self.restart_churn_notified = true;
255:        RestartChurnDecision { delay, notify }
256:    }
257:
258:    fn churn_backoff(count: u32) -> Duration {
259:        let secs = 2u64.saturating_pow(count.min(6));
260:        Duration::from_secs(secs).min(Self::BACKOFF_CAP)
261:    }
262:}
