386:/// An adopted session that predates version tracking has no trustworthy
387:/// launch-version evidence. Seed it from a single current probe so this
388:/// upgrade cycle fails closed; later upgrades compare against that honest
389:/// baseline. This mirrors `seed_prompt_nudge_baseline`: best effort probe,
390:/// durable seed, and never overwrite an existing baseline. A failed probe
391:/// yields no information at all, so nothing is written and the next
392:/// adoption retries — writing an empty value here would be indistinguishable
393:/// from a real baseline and would permanently block future seeding attempts
394:/// (see `coordinator_tmux_claude_version_is_missing`'s doc comment: an empty
395:/// value is intentionally *not* treated as missing).
396:async fn seed_claude_version_baseline_if_missing(
397:    work_db: &WorkDb,
398:    record: &mut CoordinatorTmuxRecord,
399:    version_probe: &dyn ClaudeVersionProbe,
400:) {
401:    let is_missing = match work_db.coordinator_tmux_claude_version_is_missing() {
402:        Ok(is_missing) => is_missing,
403:        Err(error) => {
404:            tracing::warn!(
405:                error = %format!("{error:#}"),
406:                "coordinator claude version baseline: failed to check whether a baseline is missing"
407:            );
408:            return;
409:        }
410:    };
411:    if !is_missing {
412:        return;
413:    }
414:    let Some(current_version) = version_probe.probe().await else {
415:        return;
416:    };
417:    match work_db.seed_coordinator_tmux_claude_version_if_absent(Some(&current_version)) {
418:        Ok(seeded) => {
419:            if seeded {
420:                record.launched_claude_version = Some(current_version);
421:            }
422:        }
423:        Err(error) => {
424:            tracing::warn!(
425:                error = %format!("{error:#}"),
426:                "coordinator claude version baseline: failed to seed baseline for adopted session"
427:            );
428:        }
429:    }
430:}
