483:/// Read the detached coordinator pane's real pid for the engine's trust
484:/// root. A Ghostty surface attached to tmux is only a client and must not be
485:/// recorded here.
486:pub(crate) async fn pane_pid(tmux: &Tmux, record: &CoordinatorTmuxRecord) -> Result<libc::pid_t> {
487:    let raw = tmux
488:        .display_message(&record.session_name, DisplayField::PanePid)
489:        .await?;
490:    let pid = raw
491:        .parse::<libc::pid_t>()
492:        .with_context(|| format!("parsing coordinator pane pid {raw:?}"))?;
493:    if pid <= 0 {
494:        bail!("coordinator pane pid is not positive: {pid}");
495:    }
496:    Ok(pid)
497:}
