499:async fn confirm_existing_intent(work_db: &WorkDb, tmux: &Tmux, record: &CoordinatorTmuxRecord) -> Result<()> {
500:    tmux.set_option(&record.session_name, SPAWN_TOKEN_OPTION, &record.spawn_token)
501:        .await
502:        .context("repairing coordinator token mirror after interrupted creation")?;
503:    tmux.set_option(&record.session_name, "remain-on-exit", "on")
504:        .await
505:        .context("repairing coordinator remain-on-exit option")?;
506:    if !work_db.record_coordinator_tmux_session_created(&record.spawn_token)? {
507:        bail!("coordinator intent changed while repairing its creation record");
508:    }
509:    Ok(())
510:}
