676:/// Create a fresh coordinator session. `reason` says why the previous one
677:/// (if any) is being replaced; it is rendered into the session-start
678:/// handoff brief the new session receives as its initial prompt (see
679:/// [`prepare_session_start_brief`]).
680:async fn start_new(spawn: &CoordinatorSpawn<'_>, reason: CoordinatorStartReason) -> Result<CoordinatorTmuxRecord> {
681:    let CoordinatorSpawn {
682:        work_db,
683:        create_tmux: tmux,
684:        model,
685:        working_directory,
686:        version_probe,
687:        ..
688:    } = *spawn;
689:    let model = model.trim();
690:    if model.is_empty() {
691:        bail!("coordinator model may not be empty");
692:    }
693:    if !working_directory.is_dir() {
694:        bail!(
695:            "coordinator session directory is not prepared: {}",
696:            working_directory.display()
697:        );
698:    }
699:    // Capture the identity of the session being replaced *before* the new
700:    // spawn intent overwrites the metadata record: the session-start brief
701:    // needs it to tell the incoming session whether the outgoing one ever
702:    // wrote a handoff after it started.
703:    let previous = work_db
704:        .coordinator_tmux_record()?
705:        .map(|record| PreviousSession::from(&record));
706:    let spawn_token = generate_token();
707:    let claude_version = version_probe.probe().await;
708:    work_db.record_coordinator_tmux_spawn_intent(
709:        COORDINATOR_SESSION_NAME,
710:        &spawn_token,
711:        model,
712:        claude_version.as_deref(),
713:    )?;
714:    let initial_prompt = prepare_session_start_brief(work_db, working_directory, previous.as_ref(), reason);
715:
716:    let mut environment = BTreeMap::from([
717:        (SPAWN_TOKEN_ENV.to_owned(), spawn_token.clone()),
718:        (SESSION_SCHEMA_ENV.to_owned(), TMUX_SESSION_SCHEMA.to_owned()),
719:    ]);
720:    if let Ok(bin_dir) = std::env::var("BOSS_BIN_DIR")
721:        && !bin_dir.is_empty()
722:    {
723:        environment.insert("BOSS_BIN_DIR".to_owned(), bin_dir.clone());
724:        environment.insert("BOSS_BIN".to_owned(), format!("{bin_dir}/boss"));
725:    }
726:    insert_color_environment(&mut environment);
727:    let quoted_model = boss_ssh_transport::shell_quote(model);
728:    // The brief rides along as `claude`'s positional initial prompt — the
729:    // same shape worker panes use for `.claude/initial-prompt.txt` — so the
730:    // incoming session consumes it on its first turn with no pane injection
731:    // and no dependence on it choosing to read a file.
732:    let command = format!(
733:        "{}unset ANTHROPIC_API_KEY; exec claude --model {quoted_model} --permission-mode auto {initial_prompt}",
734:        crate::runner::pane_spawn::path_prepend_clause("BOSS_BIN_DIR")
735:    );
736:    tmux.new_session(&NewSession {
737:        name: COORDINATOR_SESSION_NAME.to_owned(),
738:        environment,
739:        working_directory: working_directory.to_path_buf(),
740:        command,
741:    })
742:    .await
743:    .context("creating detached coordinator tmux session")?;
744:    crate::tmux_session_options::apply(tmux, COORDINATOR_SESSION_NAME)
745:        .await
746:        .context("applying Boss coordinator tmux session options")?;
747:    tmux.set_option(COORDINATOR_SESSION_NAME, SPAWN_TOKEN_OPTION, &spawn_token)
748:        .await
749:        .context("mirroring coordinator spawn token in tmux")?;
750:    tmux.set_option(COORDINATOR_SESSION_NAME, "remain-on-exit", "on")
751:        .await
752:        .context("preserving coordinator exit state for engine-side restart")?;
753:    if !work_db.record_coordinator_tmux_session_created(&spawn_token)? {
754:        bail!("coordinator session was created but its metadata intent was replaced");
755:    }
756:    seed_prompt_nudge_baseline(work_db, working_directory);
757:    let spawned_at = work_db
758:        .coordinator_tmux_record()
759:        .ok()
760:        .flatten()
761:        .and_then(|record| record.spawned_at);
762:    Ok(CoordinatorTmuxRecord {
763:        session_name: COORDINATOR_SESSION_NAME.to_owned(),
764:        spawn_token,
765:        spawn_state: "created".to_owned(),
766:        model: model.to_owned(),
767:        launched_claude_version: claude_version,
768:        spawned_at,
769:    })
770:}
