925:/// Resolve the production coordinator session directory under Application
926:/// Support. Callers pass the result into lifecycle helpers so tests can
927:/// inject a prepared temporary directory instead.
928:pub(crate) fn coordinator_working_directory() -> Result<PathBuf> {
929:    let home = std::env::var_os("HOME").ok_or_else(|| anyhow!("HOME is required for the coordinator session"))?;
930:    Ok(PathBuf::from(home)
931:        .join("Library")
932:        .join("Application Support")
933:        .join("Boss")
934:        .join("boss-session"))
935:}
