1141:    struct FakeTmux {
1142:        sessions: Vec<String>,
1143:        token: Option<String>,
1144:        pane_dead: String,
1145:        send_keys_fails: bool,
1146:        calls: Mutex<Vec<Vec<String>>>,
1147:    }
1148:
1149:    impl FakeTmux {
1150:        fn new(sessions: Vec<&str>, token: Option<&str>, pane_dead: &str) -> Self {
1151:            Self::with_send_keys_outcome(sessions, token, pane_dead, false)
1152:        }
1153:
1154:        fn with_send_keys_outcome(
1155:            sessions: Vec<&str>,
1156:            token: Option<&str>,
1157:            pane_dead: &str,
1158:            send_keys_fails: bool,
1159:        ) -> Self {
1160:            Self {
1161:                sessions: sessions.into_iter().map(str::to_owned).collect(),
1162:                token: token.map(str::to_owned),
1163:                pane_dead: pane_dead.to_owned(),
1164:                send_keys_fails,
1165:                calls: Mutex::new(Vec::new()),
1166:            }
1167:        }
1168:        fn calls(&self) -> Vec<Vec<String>> {
1169:            self.calls.lock().unwrap().clone()
1170:        }
1171:    }
1172:
1173:    #[async_trait::async_trait]
1174:    impl CommandRunner for FakeTmux {
1175:        async fn run(&self, _: &Path, args: &[OsString], cwd: Option<&Path>) -> std::io::Result<CommandOutput> {
1176:            assert!(cwd.is_none());
1177:            let args: Vec<String> = args.iter().map(|arg| arg.to_string_lossy().into_owned()).collect();
1178:            self.calls.lock().unwrap().push(args.clone());
1179:            let (success, stdout, stderr) = match args.get(2).map(String::as_str) {
1180:                Some("list-sessions") => (
1181:                    true,
1182:                    self.sessions.iter().map(|name| format!("{name}\t\n")).collect(),
1183:                    String::new(),
1184:                ),
1185:                Some("show-environment") => match &self.token {
1186:                    Some(token) => (true, format!("BOSS_SPAWN_TOKEN={token}\n"), String::new()),
1187:                    None => (false, String::new(), "unknown variable".to_owned()),
1188:                },
1189:                Some("display-message") => (true, format!("{}\n", self.pane_dead), String::new()),
1190:                Some("new-session") | Some("set-option") | Some("kill-session") => (true, String::new(), String::new()),
1191:                Some("send-keys") if self.send_keys_fails => (
1192:                    false,
1193:                    String::new(),
1194:                    "tmux server unreachable (fake failure)".to_owned(),
1195:                ),
1196:                Some("send-keys") => (true, String::new(), String::new()),
1197:                other => panic!("unexpected tmux command: {other:?}, args={args:?}"),
1198:            };
1199:            Ok(CommandOutput {
1200:                success,
1201:                code: Some(if success { 0 } else { 1 }),
1202:                stdout,
1203:                stderr,
1204:            })
1205:        }
1206:    }
