1676:    // --- operator-confirmed reset (`recreate_after_confirmation`) ---
1677:
1678:    /// Drop guard that clears `AUDIT_PATH_ENV` even if the test body panics
1679:    /// on an assertion, so a failure here can't leak the env override into
1680:    /// every later test in this binary.
1681:    struct AuditPathEnvGuard;
1682:
1683:    impl Drop for AuditPathEnvGuard {
1684:        fn drop(&mut self) {
1685:            unsafe {
1686:                std::env::remove_var(audit::AUDIT_PATH_ENV);
1687:            }
1688:        }
1689:    }
1690:
1691:    // The default `#[tokio::test]` flavor is single-threaded (`current_thread`),
1692:    // so holding this std `Mutex` across the `recreate_after_confirmation` await
1693:    // below cannot deadlock or block a sibling worker thread here; it is exactly
1694:    // what serializes this test against the other `AUDIT_PATH_ENV`/`AUDIT_PATH`
1695:    // mutators in this binary for the whole operation, not just the `set_var`
1696:    // call, which is the point (see `audit::lock_audit_globals_for_tests`'s docs).
1697:    #[allow(clippy::await_holding_lock)]
1698:    #[tokio::test]
1699:    async fn operator_reset_kills_old_session_and_creates_a_fresh_one() {
1700:        let _audit_globals = audit::lock_audit_globals_for_tests();
1701:
1702:        let (db, tmux, server, dir) = fixture(FakeTmux::new(vec![COORDINATOR_SESSION_NAME], Some("token"), "0"));
1703:        db.record_coordinator_tmux_spawn_intent(COORDINATOR_SESSION_NAME, "token", "opus", None)
1704:            .unwrap();
1705:        db.record_coordinator_tmux_session_created("token").unwrap();
1706:
1707:        let audit_dir = tempfile::tempdir().unwrap();
1708:        let audit_path = audit_dir.path().join("engine-audit.log");
1709:        let audit_already_resolved = audit::path_already_resolved_for_tests();
1710:        let _env_guard = if audit_already_resolved {
1711:            None
1712:        } else {
1713:            unsafe {
1714:                std::env::set_var(audit::AUDIT_PATH_ENV, &audit_path);
1715:            }
1716:            Some(AuditPathEnvGuard)
1717:        };
1718:
1719:        let record = recreate_after_confirmation(
1720:            &spawn_ctx(&db, &tmux, &tmux, "opus", dir.path(), &FixedProbe("2.1.238")),
1721:            "token",
1722:            CoordinatorRecreateReason::OperatorReset,
1723:        )
1724:        .await
1725:        .unwrap();
1726:
1727:        assert_ne!(record.spawn_token, "token", "the replacement must mint a fresh token");
1728:        assert_eq!(record.spawn_state, "created");
1729:        assert_eq!(record.launched_claude_version.as_deref(), Some("2.1.238"));
1730:
1731:        let calls = server.calls();
1732:        let kill = calls
1733:            .iter()
1734:            .position(|call| {
1735:                call.get(2).map(String::as_str) == Some("kill-session")
1736:                    && call.iter().any(|a| a == COORDINATOR_SESSION_NAME)
1737:            })
1738:            .expect("expected a kill-session for the coordinator");
1739:        let new = calls
1740:            .iter()
1741:            .position(|call| call.get(2).map(String::as_str) == Some("new-session"))
1742:            .expect("expected a new-session for the replacement");
1743:        assert!(
1744:            kill < new,
1745:            "the old session must be killed before the replacement is created"
1746:        );
1747:
1748:        if !audit_already_resolved {
1749:            let contents = std::fs::read_to_string(&audit_path).unwrap_or_default();
1750:            let last = contents
1751:                .lines()
1752:                .last()
1753:                .and_then(|line| serde_json::from_str::<Value>(line).ok())
1754:                .expect("expected a coordinator_recreate audit record");
1755:            assert_eq!(last["event"], "coordinator_recreate");
1756:            assert_eq!(last["outcome"], "success");
1757:            assert_eq!(last["reason"], "operator_reset");
1758:        }
1759:    }
